// @ts-ignore -- generated by the preceding build step
import { RootCircuit, assembly } from "../../dist"
import { strict as assert } from "node:assert"

const circuit = new RootCircuit()
circuit.add(
  <assembly.device>
    <board name="carrier" width={50} height={30}>
      <hole name="H1" diameter={3} pcbX={17} pcbY={8} />
      <hole name="H2" diameter={5} pcbX={-13} pcbY={-6} />
    </board>
    <assembly.drawing.page size="iso_a4">
      <assembly.drawing.partview
        partRef=".carrier"
        direction="z+"
        width={80}
        height={60}
      >
        <assembly.drawing.dimension fromRef=".H1" toRef=".H2" axis="x" />
        <assembly.drawing.dimension fromRef=".carrier" toRef=".H1" axis="x" />
      </assembly.drawing.partview>
    </assembly.drawing.page>
  </assembly.device>,
)
await circuit.renderUntilSettled()
assert.deepEqual(
  circuit.db.drawing_dimension_line
    .list()
    .map((line: { text?: string }) => line.text),
  ["30 mm", "8 mm"],
)
console.log("Built-package hole dimensions passed")
